def domain_of(m, t, q):
  for k, d in OVERRIDES.items():
    if q.startswith(k): return d
  if (m, t) in THEME2DOM: return THEME2DOM[(m, t)]
  raise SystemExit(f"Pas de domaine pour : {m} / {t} / {q[:50]}")

def check_domains(out):
  from collections import Counter
  c = Counter((x["matiere"], x["domaine"]) for x in out)
  for m, ds in DOMAINS.items():
    for d in ds:
      print(f"{c[(m,d)]:3d}  {m} · {d}", file=sys.stderr)
      assert c[(m,d)] >= 5, f"Domaine trop petit : {m} · {d}"
  assert set(c) <= {(m,d) for m in DOMAINS for d in DOMAINS[m]}

